<?phpnamespace app\api\controller\public;use app\common\controller\ApiController;use app\common\service\baidu\AipContentCensorService;class Baidu extends ApiController{    protected $noNeedLogin = ['textCensorUserDefined'];    public function initialize()    {        $this->_initialize();    }    /**     *  内容审核平台-文本     * @return void     */    public function textCensorUserDefined()    {        $AipContentCensorService = new AipContentCensorService($this->param);        $res = $AipContentCensorService->textCensorUserDefined($this->param['text']);        dd($res);    }    /**     *  内容审核平台-图片     * @return void     */    public function imageCensorUserDefined()    {        $AipContentCensorService = new AipContentCensorService($this->param);        $res = $AipContentCensorService->imageCensorUserDefined($this->param['img_url']);        dd($res);    }}